mapper.select:
select (select count(1) from survey_consignor r where r.delete_flag = 0 ) as basEntrustOrgs, (select count(1) from survey_franchisee f where f.delete_flag = 0) as basSurveyOrgs, (select count(1) from survey_investigator t where t.delete_flag = 0) as basSurveyUsers, 0 as basBillNotAcc, (select ifnull(sum(i.billing_money),0) from billing_apply a left join billing_apply_imgs i on a.id = i.bill_id where a.billing_source = 3 and a.billing_state = 3 and i.state = 1 and i.id is not null) as basTotalBillMoney, (select ifnull(sum(b.money),0) from billing_apply a left join billing_apply_accounts b on a.id = b.bill_id where a.billing_source = 3 and a.billing_state = 3 and b.state = 1 and b.id is not null) as basTotalAccMoney, (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state = 2 ) as basEntrustNotApv, (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (4,8,10,12,14,16) and s.org_assign = 0 ) as basLefanNotAss, (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (4,8,10,12,14,16) and s.org_assign = 1 ) as basOrgSurveying, (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (22,30) ) as basLefanApv, (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.survey_state in (24) ) as basEntrustApv, (select count(1) from survey_risk_case_info s where s.delete_flag = 0 and s.entrust_report_end_date is not null and s.survey_phase != 3 ) as basNotClose,
(select count(1) from survey_risk_case_info s left join survey_risk_case c on s.survey_id = c.id left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(c.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(c.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarNewEntrust, (select count(1) from survey_risk_case_info s left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarNewEntrustOK, (select ifnull(sum(s.billing_money),0) from survey_risk_case_info s left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarEntrustMoney, (select ifnull(sum(s.billing_money),0) from billing_apply_imgs s left join billing_apply a on s.bill_id = a.id where a.billing_source = 3 and a.billing_state = 3 and s.state = 1 and a.billing_enum = 2
AND date_format(s.create_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.create_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarBillMoney, (select ifnull(sum(a.money),0) from billing_apply b,billing_apply_accounts a where b.id = a.bill_id and b.billing_source = 3 and b.billing_state = 3 and b.billing_enum = 2 and a.id is not null
AND date_format(a.create_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(a.create_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarAccMoney, (0) as tarAvgMoney, (0) as tarAvgDirectionMoney, ( select count(1) from survey_case_direction d left join survey_risk_case_info s on d.survey_info_id = s.id left join survey_consignor n on s.entrust_org_id = n.id where d.delete_flag = 0 and s.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarDirectionNum, (select count(1) from survey_risk_case_info s left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag = 0 and s.is_sun = 1
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarSunRate, (select ifnull(AVG(t.num),0) from (select COUNT(DISTINCT province_id) num from survey_case_direction where survey_info_id in( select s.id from survey_risk_case_info s left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag=0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) GROUP BY survey_info_id) t ) as tarAraeRate, (select ifnull(AVG(t.days),0) from ( select ifnull(s.aging_day,0) days from survey_risk_case_info s left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag=0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) t ) as tarEffic, (select count(1) from survey_risk_case_info s left join survey_consignor n on s.entrust_org_id = n.id where s.delete_flag=0 and date_format(s.entrust_report_end_date,'%Y-%m-%d') > date_format(s.end_time,'%Y-%m-%d')
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
AND date_format(entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
) as tarEfficRate from dual

select t.price pirce,count(1) num from ( select (ifnull(s.entrust_ok_price_1,0) + ifnull(s.entrust_ok_price_2,0)) as price from survey_risk_case_info s where s.delete_flag = 0
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
AND s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
and find_in_set(s.entrust_org_id,#{entrustOrgIds,jdbcType=VARCHAR})
) t group by t.price order by t.price

select max(pirce) as maxPirceValue,min(pirce) as minPirceValue from (
    select t.price pirce,count(1) num from (
            select ifnull(s.entrust_ok_price_1 + s.entrust_ok_price_2,0) as price,s.* from survey_risk_case_info s
            where s.delete_flag = 0

                AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')


                AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')


                AND s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


                and find_in_set(s.entrust_org_id,#{entrustOrgIds,jdbcType=VARCHAR})

    ) t group by t.price
) a

select max(num) as maxNumValue,min(num) as minNumValue from (
    select t.price pirce,count(1) num from (
            select ifnull(s.entrust_ok_price_1 + s.entrust_ok_price_2,0) as price,s.* from survey_risk_case_info s
            where s.delete_flag = 0

                    AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')


                    AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')


                    AND s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}


                    and find_in_set(s.entrust_org_id,#{entrustOrgIds,jdbcType=VARCHAR})

    ) t group by t.price
) a

select t.age text,count(1) num from ( select r.age as age from survey_risk_case r left join survey_risk_case_info s on r.id = s.survey_id where s.delete_flag = 0
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
AND s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
) t group by t.age order by t.age

select t.sex text,count(1) num from ( select r.sex as sex from survey_risk_case r left join survey_risk_case_info s on r.id = s.survey_id where s.delete_flag = 0
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
AND s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
) t group by t.sex order by t.sex

select t.insure_name text,count(1) num from ( select r.insure_name as insure_name from survey_risk_case r left join survey_risk_case_info s on r.id = s.survey_id where s.delete_flag = 0
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND date_format(s.entrust_report_end_date,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
AND s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}
) t group by t.insure_name order by t.insure_name
